const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved;try{saved=JSON.parse(localStorage.getItem('ooc-demo')||'{}')}catch{saved={}}
const state={favorites:[],chats:{},created:[],credits:300,nickname:'Guest Creator',note:'',avatar:'Traveler',mode:'Basic',...saved};
const realCharacters=window.OOC_CHARACTERS||[];
let chatError='',activeRequest=null,serviceReady=null;
const drafts={},account=window.storyAccount;let walletBusy=false;
const analytics=window.storyAnalytics||{track(){},pageView(){},scan(){},session:null,flow:()=>''};
const creditIcon='<span class="credit-icon" aria-hidden="true">✦</span>';
window.addEventListener('accountchange',()=>{if(['credits','profile'].includes(page))render();else historyList();});
let page='character',genre='Main',query='',sort='Popular',searchType='all',hero=0,selected=null,step=0,draft={type:'story',name:'',description:'',intro:'',prompt:'',tags:'Fantasy',image:''},busy=false;
const genres=['Main','Rankings','Fantasy','Romance','School Life','Simulation','Adventure','Slice of Life'];
const original=window.STORYLOVE_STORIES||[];
function items(){return [...realCharacters,...state.created,...original]}
function persist(){try{localStorage.setItem('ooc-demo',JSON.stringify(state))}catch{toast('本地储存已满，本次聊天可能无法保存。')}historyList()}
function formatReply(s){return esc(s).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*\n]+)\*/g,'<em>$1</em>').replace(/^[-*] /gm,'• ');}
function toast(s){$('#toast').textContent=s;$('#toast').style.transform='translateX(-50%) translateY(0)';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.transform='',2400)}
function nav(p){page=p;query='';genre='Main';location.hash=p;render();window.scrollTo(0,0)}
function historyList(){$('#historyList').innerHTML=Object.keys(state.chats).reverse().map(id=>{const t=items().find(t=>t.id===id);return t?`<button class="historyitem" data-chat="${esc(id)}"><img src="${esc(t.image)}" alt=""><span>${esc(t.name)}</span></button>`:''}).join('');$('#profileBtn').innerHTML=`◉ <span>${esc(account.user?.user_metadata?.full_name||state.nickname)}</span><span>⚙</span>`}
function card(t,i,rank=false){return `<button class="card ${t.type==='character'?'character':''}" data-title="${esc(t.id)}"><div class="cover"><img src="${esc(t.image)}" alt="${esc(t.name)}" loading="lazy" decoding="async"><span class="badge">${t.real?(t.type==='story'?'互动小说':'角色聊天'):(t.type==='character'?'Character':'Story')}</span>${rank?`<span class="rank">${i+1}</span>`:''}</div><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><div class="meta">@${esc(t.real?t.origin:'@'+(t.creator||state.nickname))} · ${esc(t.real?t.mood:'Preview')}</div></button>`}
function section(name,ts,rank=false){return `<section class="section"><div class="sectionhead"><h2>${esc(name)}</h2><button data-all="${esc(name)}">View All ›</button></div><div class="cards">${ts.map((t,i)=>card(t,i,rank)).join('')}</div></section>`}
function footer(){return `<footer class="footer"><div><strong>StoryLove</strong><p>The Playable Anime</p><p>角色聊天实验室 · 非官方同人原型</p></div><div><b>Explore</b><button data-page="story">Story</button><button data-page="character">Character</button><button data-page="titles">My Titles</button></div><div><b>Support</b><button data-action="help">Contact & Support</button><button data-action="about">About this demo</button></div></footer>`}
function home(){
 const h=realCharacters[hero%realCharacters.length];
 const featured=realCharacters.filter(t=>genre==='Main'||genre==='Rankings'||t.genre===genre);
 return `<section class="hero characterhero"><div class="herocopy"><span class="eyebrow">StoryLove · CHARACTER CHATS</span><h1>一次相遇，<br>一段属于你的故事。</h1><p>和鲜明的角色自然交谈。冒险、日常，或只是分享今天。</p><button class="explore" data-chat="${h.id}">与 ${esc(h.name)} 交谈 ↗</button><span class="hero-caption">${esc(h.scene)} · ${esc(h.mood)}</span></div><div class="heroart"><img src="${esc(h.image)}" alt="${esc(h.name)}" decoding="async" fetchpriority="high"><div class="hero-art-caption"><small>${esc(h.origin)}</small><strong>${esc(h.name)}</strong></div></div><div class="herodots">${realCharacters.map((c,i)=>`<button data-feature="${i}" class="${i===hero%realCharacters.length?'selected':''}" aria-label="查看${esc(c.name)}"></button>`).join('')}</div></section><div class="content"><section class="section featured"><div class="sectionhead"><div><span class="eyebrow">MEET YOUR CHARACTERS</span><h2>从谁的故事开始？</h2></div><span class="quiet">${realCharacters.length} 位角色 · ${realCharacters.length} 种性格</span></div><div class="cards featured-cards">${featured.map((t,i)=>card(t,i)).join('')}</div><p class="fan-note">角色设定与开场为原创同人内容，与原作权利人无关联。聊天由 AI 生成，可能出现错误。</p></section>${page==='story'?section('走进一段互动小说',original):''}</div>${footer()}`;
}
function head(title,extra=''){return `<div class="pagehead"><h1>${esc(title)}</h1>${extra}</div>`}
function empty(title,description,action='Explore',p='story'){return `<div class="empty"><div style="font-size:46px">✱</div><b>${esc(title)}</b><p>${esc(description)}</p><button class="secondary" data-page="${p}">${action}</button></div>`}
function render(){if(page==='chat'&&$('#message')&&selected)drafts[$('#message').dataset.character]=$('#message').value;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='story'||page==='character')app.innerHTML=home();else if(page==='detail')app.innerHTML=detail();else if(page==='chat')app.innerHTML=chat();else if(page==='search')app.innerHTML=head('Search')+`<div class="content"><div class="searchbox">⌕ <input id="search" aria-label="Search titles" placeholder="Search stories, characters, creators..." value="${esc(query)}"><button data-action="clearSearch">×</button></div><div class="sectionhead"><div class="steps"><button class="chip selected" data-searchtype="all">All</button><button class="chip" data-searchtype="story">Story</button><button class="chip" data-searchtype="character">Character</button></div><select id="sort" style="width:160px"><option>Popular</option><option ${sort==='Latest First'?'selected':''}>Latest First</option></select></div><div id="searchResults"></div></div>`;else if(page==='titles')app.innerHTML=head('My Titles',`<button class="primary" data-action="create">＋ Create</button>`)+`<div class="content"><div class="steps"><button class="chip selected" data-action="createdTab">Created</button><button class="chip" data-action="favoritesTab">Liked</button></div><div id="mygrid" style="margin-top:28px">${state.created.length?`<div class="cards">${state.created.map((t,i)=>card(t,i)).join('')}</div>`:empty('Create your own world','Bring your stories and characters to life.','Explore')}</div></div>`;else if(page==='history')app.innerHTML=head('History')+`<div class="content">${Object.keys(state.chats).length?`<div class="cards">${items().filter(t=>state.chats[t.id]).map((t,i)=>card(t,i)).join('')}</div>`:empty('Your story is waiting','Start a conversation to see it here.')}</div>`;else if(page==='notifications')app.innerHTML=head('Your notifications')+empty('No notifications',"You don’t have any notifications yet.");else if(page==='credits')app.innerHTML=credits();else if(page==='profile')app.innerHTML=profile();else if(page==='builder')app.innerHTML=builder();if(page==='search'){searchType='all';searchResults();}historyList();if(page==='chat'){if($('#message'))$('#message').value=drafts[selected.id]||'';scrollChat()}analytics.pageView(['chat','detail'].includes(page)?page+'/'+selected?.id:page)}
function searchResults(){let ts=items().filter(t=>(searchType==='all'||(t.type||'story')===searchType)&&(t.name+' '+t.description+' '+t.genre+' '+t.creator).toLowerCase().includes(query.toLowerCase()));if(sort==='Latest First')ts.reverse();$('#searchResults').innerHTML=ts.length?`<div class="cards">${ts.map((t,i)=>card(t,i)).join('')}</div>`:empty('No results found','Try another keyword.','Explore');}
function detail(){const t=selected;return head(t.real?(t.type==='story'?'故事档案':'角色档案'):'故事预览',`<button data-page="character" aria-label="返回角色">✕</button>`)+`<div class="detail"><div class="detailtop"><img src="${esc(t.image)}" alt="${esc(t.name)}"><div><span class="eyebrow">${esc(t.origin||t.genre)}</span><h1>${esc(t.name)}</h1><p>${esc(t.description)}</p><div class="tags"><span class="chip">${esc(t.mood||t.genre)}</span><span class="chip">${t.type==='story'&&t.real?'StoryLove 原创故事':t.real?'非官方同人':'本地草稿'}</span></div><div class="detailactions"><button class="primary" data-chat="${esc(t.id)}">${state.chats[t.id]?'继续对话':'开始对话'} →</button><button class="secondary" data-like="${t.id}">${state.favorites.includes(t.id)?'♥ 已收藏':'♡ 收藏'}</button><button class="secondary" data-action="share">↗ 分享</button></div></div></div><div class="detailtext"><h2>故事从这里开始</h2><p class="opening">${esc(t.intro)}</p><h2>关于这段对话</h2><p>${t.real?'近期聊天用于保持上下文，对话记录只保存在当前浏览器。发送后，最近最多20条消息会交给AI服务处理。':'此故事是界面预览，暂未接入真实聊天。'}</p></div></div>`}
function startChat(id){
 const next=items().find(t=>t.id===id);if(!next)return;
 if(activeRequest){activeRequest.abort();activeRequest=null;busy=false;}
 selected=next;chatError='';analytics.track('chat_start',{character_id:id,kind:next.type||'character'});
 if(!state.chats[id])state.chats[id]=[{role:'assistant',text:selected.intro||'欢迎。'}];
 // An interrupted draft is never treated as a complete model response.
 state.chats[id]=state.chats[id].filter(m=>!m.pending);
 if(state.chats[id].at(-1)?.role==='user')chatError='上一条消息尚未完成回复，可以重试。';
 page='chat';location.hash='chat/'+id;persist();render();
}
function chat(){const ms=state.chats[selected.id]||[];return `<div class="chat-layout"><div class="chat"><div class="chathead"><button data-action="backDetail" aria-label="返回角色档案">‹</button><div class="chat-title"><b>${esc(selected.name)}</b><small>${esc(selected.scene||(selected.type==='story'?'互动小说':'角色场景'))}</small></div><button class="secondary new-chat" data-action="restartChat" ${busy?'disabled':''}>新对话</button><button data-action="chatMenu" aria-label="对话菜单">⋯</button></div><div class="messages" id="messages"><div class="chatintro"><img src="${esc(selected.image)}" alt="${esc(selected.name)}"><span class="eyebrow">${esc(selected.origin||'故事预览')}</span><h2>${esc(selected.name)}</h2><p>${esc(selected.description)}</p></div>${ms.map((m,i)=>`<div class="msg ${m.role} ${m.pending?'pending':''}"><small>${m.role==='user'?esc(state.avatar):esc(selected.name)}</small><div class="bubble" ${m.pending?'id="streamBubble"':''}>${m.pending&&!m.text?'<span class="typing"><i></i><i></i><i></i></span>':(m.role==='assistant'?formatReply(m.text):esc(m.text))}</div>${m.role==='assistant'&&i===ms.length-1&&i>0&&!m.pending?`<button data-regenerate="${i}" ${busy?'disabled':''}>↻ 重新生成</button>`:''}</div>`).join('')}<div id="chatError" class="chat-error" role="alert" ${chatError?'':'hidden'}><span>${esc(chatError)}</span><button class="secondary" data-action="retryChat" ${busy?'disabled':''}>重试</button></div></div><div class="composer">${ms.length<=1?`<div class="suggestions">${(selected.suggestions||[]).map(t=>`<button data-suggestion="${esc(t)}">${esc(t)}</button>`).join('')}</div>`:''}<form id="sendForm" class="inputrow"><textarea id="message" maxlength="4000" rows="1" placeholder="说些什么，或描述你的行动…" data-character="${esc(selected.id)}" aria-label="消息"></textarea><button type="submit" aria-label="发送消息" ${busy?'disabled':''}>↑</button>${busy?'<button type="button" class="stop-generation" data-action="stopChat">停止</button>':''}</form><div class="demohint">${busy?'正在回复…':selected.real?(selected.type==='story'?'互动小说':'AI 角色')+' · 对话保存在此浏览器 · Enter 发送，Shift+Enter 换行':'占位故事暂未接入聊天'}${serviceReady===false&&selected.real?' · 服务待连接':''}</div></div></div><aside class="character-rail"><img src="${esc(selected.image)}" alt=""><div><span class="eyebrow">${esc(selected.origin||'PREVIEW')}</span><h2>${esc(selected.name)}</h2><p>${esc(selected.mood||selected.genre)}</p><p>${esc(selected.description)}</p><small>你的行动，由你决定。</small></div></aside></div>`}
function scrollChat(force=true){const m=$('#messages');if(m&&(force||m.scrollHeight-m.scrollTop-m.clientHeight<140))m.scrollTop=m.scrollHeight}
function recentMessages(ms){const history=ms.filter(m=>!m.pending&&!m.failed&&m.text.trim()).slice(-20);let size=0;const result=[];for(let i=history.length-1;i>=0;i--){if(size+history[i].text.length>20000)break;size+=history[i].text.length;result.unshift({role:history[i].role,content:history[i].text});}return result;}
async function generate(){
 if(busy||!selected)return;if(!selected.real){chatError='这个故事仍是预览。请选择 Lara、蒂法或春丽开始真实聊天。';render();return;}
 const id=selected.id,ms=state.chats[id];if(ms.at(-1)?.role!=='user')return;
 const messages=recentMessages(ms);busy=true;chatError='';const controller=new AbortController();activeRequest=controller;
 const startedAt=performance.now();let replyMeta={},firstDelta=null;
 const pending={role:'assistant',text:'',pending:true};ms.push(pending);render();
 let frame=0;const paint=()=>{frame=0;const bubble=$('#streamBubble');if(page==='chat'&&selected?.id===id&&activeRequest===controller&&bubble){const m=$('#messages'),follow=m.scrollHeight-m.scrollTop-m.clientHeight<140;bubble.innerHTML=formatReply(pending.text);if(follow)scrollChat();}};
 const timer=setTimeout(()=>controller.abort(),55000);
 let succeeded=false;
 try{
  const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json',...(account.user&&account.provider!=='netlify'?{Authorization:'Bearer '+(await account.client.auth.getSession()).data.session?.access_token}:{})},body:JSON.stringify({characterId:id,messages}),signal:controller.signal});
  if(!response.ok){let error;try{error=(await response.json()).error}catch{}throw Error(error||(response.status===429?'请求较多，请稍等一分钟再试。':'聊天服务暂时不可用，请重试。'));}
  if(!response.headers.get('content-type')?.includes('text/event-stream')||!response.body)throw Error('聊天接口尚未部署，请稍后再试。');
  const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',doneEvent=false;
  const line=raw=>{if(!raw.startsWith('data:'))return;const e=JSON.parse(raw.slice(5));if(e.error)throw Error(e.error);if(e.done){doneEvent=true;replyMeta={prompt_version:e.promptVersion,provider:e.provider,model:e.model};}if(e.delta){if(firstDelta===null)firstDelta=performance.now()-startedAt;pending.text+=e.delta;if(!frame)frame=requestAnimationFrame(paint);}};
  try{while(true){const {done,value}=await reader.read();buffer+=done?decoder.decode():decoder.decode(value,{stream:true});const lines=buffer.split('\n');buffer=lines.pop();for(const l of lines)line(l);if(done){if(buffer)line(buffer);break;}}}finally{await reader.cancel().catch(()=>{});}
  if(!doneEvent||!pending.text)throw Error('回复中断，请重试。');
  delete pending.pending;succeeded=true;analytics.track('reply_complete',{character_id:id,duration_ms:Math.round(performance.now()-startedAt),first_delta_ms:Math.round(firstDelta||0),...replyMeta});
 }catch(e){analytics.track('reply_failed',{character_id:id,reason:controller.signal.aborted?'aborted':'service_error',duration_ms:Math.round(performance.now()-startedAt)});const index=ms.indexOf(pending);if(index>=0)ms.splice(index,1);if(activeRequest===controller&&selected?.id===id)chatError=controller.signal.aborted?'回复已中断，请重试。':e.message;}
 finally{clearTimeout(timer);if(frame)cancelAnimationFrame(frame);const current=activeRequest===controller;if(current){activeRequest=null;busy=false;}persist();if(current&&page==='chat'&&selected?.id===id){const box=$('#messages'),top=box?.scrollTop,follow=!box||box.scrollHeight-box.scrollTop-box.clientHeight<140;render();if(!follow&&$('#messages'))$('#messages').scrollTop=top;$('#message')?.focus();}}
 return succeeded;
}
function send(text){text=text.trim();if(!text||busy)return;if(!selected.real)return toast('此故事是预览，请选择已接入聊天的角色。');if(chatError&&state.chats[selected.id]?.at(-1)?.role==='user'){toast('请重试上一条消息，或开始新对话。');return;}if(text.length>4000)return toast('每条消息最多4000个字符。');analytics.track('message_send',{character_id:selected.id,message_count:state.chats[selected.id].filter(m=>m.role==='user').length+1});drafts[selected.id]='';if($('#message'))$('#message').value='';state.chats[selected.id].push({role:'user',text});persist();generate();}
function openModal(html){modal.innerHTML=`<button class="close" data-action="closeModal" aria-label="Close">×</button>${html}`;modal.showModal()}
function credits(){const w=account.wallet;return head('Credits')+`<div class="content wallet-page"><div class="balance"><span class="eyebrow">YOUR NEXT CHAPTER</span><p>故事灵感，随时续写</p><b>${creditIcon} ${w?w.balance.toLocaleString():'—'}</b><div class="wallet-actions"><button class="primary" data-action="checkin" ${walletBusy||w?.checked?'disabled':''}>${walletBusy==='checkin'?'正在领取…':w?.checked?'✓ 今日已签到':'每日签到 · +100'}</button><button class="secondary" data-action="creditHistory">查看流水</button>${!account.user?'<button class="secondary" data-action="login">Google 登录</button>':''}</div><small>每日 00:00（上海时间）刷新 · ${account.user?(account.walletMode==='test'?'Sandbox 测试钱包 · 不计入正式余额':'账户钱包'):'登录后领取并保存 credits'}</small></div>${account.error?`<p class="account-notice" role="status">${esc(account.error)} <button data-action="refreshWallet">重试</button></p>`:''}<h2>为下一段故事准备灵感</h2><p class="quiet">通过 Stripe 安全付款，到账后余额自动更新。</p><div class="plans">${window.STORYLOVE_CREDIT_PACKS.map(({credits:n,amount,label})=>{const p=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(amount/100);return `<div class="plan"><span class="eyebrow">${label}</span><h2>${creditIcon} ${n.toLocaleString()}</h2><p>${p} USD</p><button class="primary" data-refill="${n}" ${walletBusy?'disabled':''}>${walletBusy==='checkout:'+n?'正在打开付款…':account.payments?'充值 Credits':'充值即将开放'}</button></div>`}).join('')}</div><p class="demohint">${account.payments?'付款成功以账户流水为准；取消或失败不会扣款。':'付款尚未配置，当前不会收取费用。'} · 当前角色聊天暂不扣除 credits。</p></div>`}
function profile(){return head('My Account')+`<div class="content" style="max-width:900px"><h2>${esc(account.user?.user_metadata?.full_name||state.nickname)}</h2><p class="account-notice">${account.user?'已使用 Google 登录':esc(account.error||'登录以领取每日 credits')}</p><div class="settingrow"><div>Nickname<small>Your creator profile</small></div><input id="nickname" value="${esc(state.nickname)}"></div><div class="settingrow"><div>Appearance<small>Personalize your interface</small></div><select id="theme"><option value="dark">Dark</option><option value="light" ${state.theme==='light'?'selected':''}>Light</option></select></div><div class="settingrow"><div>Language</div><select id="language"><option>English</option><option>简体中文</option><option>日本語</option><option>한국어</option></select></div><div class="settingrow"><div>Avatars<small>How characters recognize you</small></div><input id="avatar" value="${esc(state.avatar)}"></div><label>User Note</label><textarea id="userNote" placeholder="仅保存在浏览器，本阶段不会发送给角色">${esc(state.note)}</textarea><div style="margin-top:20px"><button class="primary" data-action="saveProfile">Save Changes</button><button class="secondary" data-action="${account.user?'logout':'login'}">${account.user?'退出登录':'使用 Google 登录'}</button></div><div class="settingrow"><span>Titles you like</span><button class="secondary" data-action="showLiked">View favorites →</button></div><div class="settingrow"><span>Help Center</span><button class="secondary" data-action="help">Open Guide →</button></div></div>`}
const steps=['Character Setup','Intro','Prompt','Advanced Features','Character Details'];
function builder(){const body=step===0?`<label>Type</label><select id="draftType"><option value="story">Story</option><option value="character" ${draft.type==='character'?'selected':''}>Character</option></select><label>Title image</label><label class="upload" for="upload">${draft.image?`<img src="${draft.image}" alt="Preview">`:'＋ Upload image'}</label><input id="upload" type="file" accept="image/*" hidden><label>Name *</label><input id="draftName" maxlength="80" placeholder="Give your world a name" value="${esc(draft.name)}"><label>One-line Introduction</label><textarea id="draftDescription" placeholder="What makes your title special?">${esc(draft.description)}</textarea>`:step===1?`<label>Opening Greeting</label><textarea id="draftIntro" style="height:260px" placeholder="Set the scene and invite the user into your world...">${esc(draft.intro)}</textarea>`:step===2?`<label>Character Prompt</label><textarea id="draftPrompt" maxlength="3000" style="height:260px" placeholder="Personality, tone, appearance, relationships, and world setting...">${esc(draft.prompt)}</textarea><p class="demohint">Up to 3,000 characters</p>`:step===3?`<label>Suggested Replies</label><textarea placeholder="Example actions or dialogue...">Say hello\nExplore the world\nAsk a question</textarea><label>Keyword Book</label><textarea placeholder="Add background and world-building details..."></textarea><button class="secondary" data-action="advancedPreview" style="margin-top:16px">Preview settings</button>`:`<label>Genre</label><select id="draftGenre">${genres.slice(2).map(g=>`<option ${draft.tags===g?'selected':''}>${g}</option>`).join('')}</select><label>Visibility</label><select><option>Private</option><option>Public (demo)</option></select><h2>${esc(draft.name||'Untitled')}</h2><p style="color:#999">${esc(draft.description||'Your new story is ready.')}</p><p class="demohint">Publishing saves your title locally in this demo.</p>`;return head('Create a '+(draft.type==='character'?'Character':'Story'),'<button data-page="titles">✕</button>')+`<div class="builder"><div class="steps">${steps.map((s,i)=>`<button class="step ${i===step?'current':''}" data-step="${i}">${i+1}. ${s}</button>`).join('')}</div><h2 style="margin-top:32px">${steps[step]}</h2>${body}<div class="builderfooter"><button class="secondary" data-action="builderPrev">${step?'Back':'Cancel'}</button><button class="primary" data-action="builderNext">${step===4?'Publish Title':'Next Step →'}</button></div></div>`}
function captureDraft(){if($('#draftName')){draft.name=$('#draftName').value;draft.description=$('#draftDescription').value;draft.type=$('#draftType').value}if($('#draftIntro'))draft.intro=$('#draftIntro').value;if($('#draftPrompt'))draft.prompt=$('#draftPrompt').value;if($('#draftGenre'))draft.tags=$('#draftGenre').value}
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;searchResults()}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;searchResults()}if(e.target.id==='rankingPeriod'){toast(e.target.value+' rankings');$('.cards').innerHTML=original.slice().reverse().map((t,i)=>card(t,i,true)).join('')}if(e.target.id==='theme'){state.theme=e.target.value;document.body.classList.toggle('light',state.theme==='light');persist()}if(e.target.id==='language')toast('Language setting saved (demo content remains English)');if(e.target.id==='upload'&&e.target.files[0]){if(e.target.files[0].size>4e6)return toast('Choose an image smaller than 4 MB');const r=new FileReader();r.onload=()=>{draft.image=r.result;captureDraft();render()};r.readAsDataURL(e.target.files[0])}});
