document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.page){if(modal.open)modal.close();nav(d.page);return}if(b.id==='collapse'){document.body.classList.toggle('collapsed');return}if(d.title){analytics.track('character_view',{character_id:d.title});selected=items().find(t=>t.id===d.title);page='detail';location.hash='title/'+d.title;render();window.scrollTo(0,0);return}if(d.chat){startChat(d.chat);return}if(d.genre){genre=d.genre;render();return}if(d.feature!==undefined){hero=Number(d.feature);render();return}if(d.hero){hero=(hero+Number(d.hero)+12)%12;render();return}if(d.all){genre=d.all==='Trending Now'?'Rankings':genre;app.innerHTML=head(d.all)+`<div class="content"><div class="cards">${items().map((t,i)=>card(t,i)).join('')}</div></div>`;window.scrollTo(0,0);return}if(d.like){const i=state.favorites.indexOf(d.like);i<0?state.favorites.push(d.like):state.favorites.splice(i,1);persist();render();return}if(d.suggestion){$('#message').value=d.suggestion;$('#message').focus();return}if(d.searchtype){searchType=d.searchtype;document.querySelectorAll('[data-searchtype]').forEach(x=>x.classList.toggle('selected',x===b));toast(d.searchtype==='all'?'Showing all titles':'Showing '+d.searchtype+' titles');searchResults();return}if(d.refill){if(walletBusy)return;if(!account.user){try{await account.login()}catch(e){toast(e.message)}return;}walletBusy='checkout:'+d.refill;render();try{const pendingKey='storylove-checkout:'+account.user.id+':'+d.refill;let pending;try{pending=JSON.parse(sessionStorage.getItem(pendingKey))}catch{}if(!pending||Date.now()-pending.created>1800000){pending={id:crypto.randomUUID(),created:Date.now()};sessionStorage.setItem(pendingKey,JSON.stringify(pending));}const flow=pending.id;analytics.track('checkout_start',{pack:Number(d.refill),flow_id:flow});const result=await account.api('checkout',{pack:Number(d.refill),request_id:flow,analytics:{session_id:analytics.session,flow_id:flow}});analytics.track('checkout_redirect',{pack:Number(d.refill),flow_id:flow});analytics.beacon?.();location.assign(result.url);}catch(e){analytics.track('checkout_failed',{pack:Number(d.refill),reason:'unavailable'});toast(e.message)}finally{walletBusy=false;render()}return;}if(d.step){captureDraft();step=Number(d.step);render();return}if(d.edit!==undefined){const i=Number(d.edit);openModal(`<h2>Edit message</h2><textarea id="editText">${esc(state.chats[selected.id][i].text)}</textarea><div class="modalactions"><button class="primary" data-saveedit="${i}">Save</button></div>`);return}if(d.saveedit!==undefined){state.chats[selected.id][Number(d.saveedit)].text=$('#editText').value;persist();modal.close();render();return}if(d.delete!==undefined){state.chats[selected.id].splice(Number(d.delete),1);persist();render();return}if(d.regenerate!==undefined){if(busy)return;analytics.track('conversation_regenerate',{character_id:selected.id});state.chats[selected.id].splice(Number(d.regenerate));persist();generate();return}
switch(d.action){case'retryChat':generate();break;case'closeModal':modal.close();break;case'dismiss':$('.notice').remove();break;case'clearSearch':query='';$('#search').value='';searchResults();break;case'backDetail':nav('character');break;case'share':try{await navigator.clipboard.writeText(location.href);toast('Link copied')}catch{toast('Copy this page’s address to share')}break;case'comment':{const t=$('#comment').value.trim();if(t){const p=document.createElement('p');p.textContent=state.nickname+': '+t;$('#comments').appendChild(p);$('#comment').value='';toast('Comment added in this session')}break}case'create':analytics.track('title_create_start');step=0;page='builder';render();break;case'builderPrev':captureDraft();if(step){step--;render()}else nav('titles');break;case'builderNext':captureDraft();if(!draft.name.trim()){step=0;render();toast('Please enter a name');return}if(step<4){step++;render()}else{const t={id:'created-'+Date.now(),name:draft.name,description:draft.description,intro:draft.intro||'“Welcome. Your story begins now.”',prompt:draft.prompt,type:draft.type,genre:draft.tags,image:draft.image||original[0].image,creator:state.nickname,plays:'New'};state.created.unshift(t);analytics.track('title_create_complete',{kind:t.type});persist();draft={type:'story',name:'',description:'',intro:'',prompt:'',tags:'Fantasy',image:''};nav('titles');toast('Title published in your browser')}break;case'advancedPreview':toast('Advanced settings are placeholders in this demo');break;case'favoritesTab':case'showLiked':if(page!=='titles'){page='titles';render()}$('#mygrid').innerHTML=state.favorites.length?`<div class="cards">${items().filter(t=>state.favorites.includes(t.id)).map((t,i)=>card(t,i)).join('')}</div>`:empty('Your favorites list is empty','Like a title to collect your preferred titles here');break;case'createdTab':render();break;case'checkin':{if(walletBusy)return;if(!account.user){try{await account.login()}catch(e){toast(e.message)}break;}walletBusy='checkin';render();analytics.track('checkin_start');try{account.wallet=await account.api('checkin',{});analytics.track('checkin_complete',{outcome:account.wallet.claimed?'claimed':'already_claimed'});toast(account.wallet.claimed?'已领取 100 credits':'今日已签到，明天再来')}catch(e){analytics.track('checkin_failed',{reason:'unavailable'});toast(e.message)}finally{walletBusy=false;render()}break}case'refreshWallet':await account.refreshWallet();break;case'creditHistory':{if(!account.user){toast('请先登录查看账户流水');break;}await account.refreshWallet();openModal(`<h2>Credits 流水</h2>${account.wallet?.history?.length?'<div class="ledger">'+account.wallet.history.map(x=>`<div class="settingrow"><span>${x.kind==='checkin'?'每日签到':'充值'}<small>${esc(new Date(x.created_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))}</small></span><b>+${esc(x.delta)}</b></div>`).join('')+'</div>':'<p>暂无流水。</p>'}`);break;}case'saveProfile':state.nickname=$('#nickname').value||'Guest Creator';state.avatar=$('#avatar').value||'Traveler';state.note=$('#userNote').value;persist();toast('Changes saved');break;case'login':try{await account.login()}catch(e){toast(e.message)}break;case'logout':try{await account.logout();render();toast('已退出登录')}catch(e){toast(e.message)}break;case'stopChat':analytics.track('generation_stop',{character_id:selected?.id});activeRequest?.abort();break;case'mode':openModal(`<h2>Conversation Mode</h2>${['Basic','Skillful','Extensive','Superb','Premium'].map(m=>`<button class="settingrow" style="width:100%" data-mode="${m}"><span>${m}</span><span>${m===state.mode?'✓':'Select'}</span></button>`).join('')}<p class="demohint">Mode selection is a UI demo.</p>`);break;case'chatSettings':openModal(`<h2>Session Settings</h2><label>Avatar name</label><input id="sessionAvatar" value="${esc(state.avatar)}"><label>User Note</label><textarea id="sessionNote">${esc(state.note)}</textarea><label>Output Length</label><input type="range" min="200" max="2000" value="800"><button class="secondary" style="margin-top:16px" data-action="memories">Memories</button><div class="modalactions"><button class="primary" data-action="saveSession">Save</button></div>`);break;case'saveSession':state.avatar=$('#sessionAvatar').value;state.note=$('#sessionNote').value;persist();modal.close();render();break;case'memories':openModal('<h2>Memories</h2><div class="steps"><span class="chip selected">Long-term</span><span class="chip">Temporary</span><span class="chip">Relationships</span><span class="chip">Goals</span></div><label>Long-term memory</label><textarea id="memory" placeholder="Add important events or facts...">'+esc(state.memory||'')+'</textarea><div class="modalactions"><button class="primary" data-action="saveMemory">Save</button></div>');break;case'saveMemory':state.memory=$('#memory').value;persist();modal.close();toast('Memory saved');break;case'chatMenu':openModal('<h2>Conversation</h2><button class="settingrow" style="width:100%" data-action="exportChat">Export conversation ↓</button><button class="settingrow" style="width:100%" data-action="restartChat">Start a new conversation ↻</button>');break;case'restartChat':if(busy)break;analytics.track('conversation_restart',{character_id:selected.id});state.chats[selected.id]=[{role:'assistant',text:selected.intro}];chatError='';persist();if(modal.open)modal.close();render();toast('已开始新对话');break;case'exportChat':{analytics.track('conversation_export',{character_id:selected.id});const data=state.chats[selected.id].map(m=>(m.role==='user'?state.avatar:selected.name)+': '+m.text).join('\n\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'text/plain'}));a.download='conversation.txt';a.click();URL.revokeObjectURL(a.href);modal.close();break}case'help':openModal(`<h2>StoryLove Guide</h2><p>Explore a title, choose Start Story, then type what you say or do.</p><p>Use Session Settings to edit your avatar, notes, and memories. Use Create to build a new story or character.</p><p>${realCharacters.map(c=>esc(c.name)).join("、")}通过服务端连接真实AI；原创小说也支持流式互动。最近最多20条消息提供上下文。</p>`);break;case'about':openModal('<h2>About this recreation</h2><p>A standalone interface recreation based on publicly available OOC styles and feature documentation.</p><p>StoryLove 是独立的非官方角色聊天原型。账户与支付需完成服务配置；自建故事暂保存在当前浏览器，既有角色及作品名称归原权利人所有。</p>');break;}if(d.mode){state.mode=d.mode;persist();modal.close();render()}});
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(h.startsWith('title/')){selected=items().find(t=>t.id===h.slice(6));if(selected){page='detail';render()}}else if(h.startsWith('chat/')){if(selected?.id!==h.slice(5)||page!=='chat')startChat(h.slice(5))}else if(['story','character','titles','credits','history','profile','search','notifications'].includes(h)&&h!==page){page=h;render()}});
document.body.classList.toggle('light',state.theme==='light');if(!location.hash)render();if(location.hash){const h=location.hash.slice(1);if(h.startsWith('title/')){selected=items().find(t=>t.id===h.slice(6));if(selected){page='detail';render()}}else if(h.startsWith('chat/'))startChat(h.slice(5));else if(['story','character','titles','credits','history','profile','search','notifications'].includes(h)){page=h;render()}}

